-- Vistas
CREATE OR REPLACE VIEW `VW_REPARTIDOR_TOTAL_AMONESTACIONES` (`REPARTIDOR_ID`, `TOTAL_AMONESTACIONES`) AS
SELECT
    r.repartidor_id,
    COUNT(CASE WHEN a.activa = 'S' THEN 1 END) AS total_amonestaciones
FROM repartidor r
LEFT JOIN amonestacion_repartidor a
       ON a.repartidor_id = r.repartidor_id
GROUP BY r.repartidor_id;

CREATE OR REPLACE VIEW `VW_TOTAL_PEDIDOS_POR_CLIENTE` (`CLIENTE_ID`, `CLIENTE`, `TOTAL_PEDIDOS`) AS
SELECT
    c.cliente_id,
    u.nombre_completo AS cliente,
    COUNT(p.pedido_id) AS total_pedidos
FROM cliente c
JOIN usuario u
  ON u.usuario_id = c.usuario_id
LEFT JOIN pedido p
  ON p.cliente_id = c.cliente_id
GROUP BY c.cliente_id, u.nombre_completo;

CREATE OR REPLACE VIEW `VW_TOTAL_VENDIDO_POR_RESTAURANTE` (`RESTAURANTE_ID`, `RESTAURANTE`, `TOTAL_VENDIDO`, `TOTAL_PEDIDOS`) AS
SELECT
    r.restaurante_id,
    r.nombre AS restaurante,
    IFNULL(SUM(f.monto_total), 0) AS total_vendido,
    COUNT(DISTINCT p.pedido_id) AS total_pedidos
FROM restaurante r
LEFT JOIN pedido p
       ON p.restaurante_id = r.restaurante_id
LEFT JOIN factura f
       ON f.pedido_id = p.pedido_id
GROUP BY r.restaurante_id, r.nombre;

ALTER TABLE FACTURA
ADD COLUMN TARJETA_RESUMEN VARCHAR(80) NULL AFTER MEDIO_PAGO;

